<?php $tot=['students'=>0,'marked'=>0,'present'=>0,'absent'=>0,'late'=>0,'leave'=>0];foreach($rows as$r){$tot['students']+=(int)$r['student_count'];$tot['marked']+=(int)$r['marked'];$tot['present']+=(int)$r['present_count'];$tot['absent']+=(int)$r['absent_count'];$tot['late']+=(int)$r['late_count'];$tot['leave']+=(int)$r['leave_count'];}$rate=$tot['marked']?round($tot['present']/$tot['marked']*100,1):0;?>
<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb"><a href="<?=url('/admin/dashboard')?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Classwise Attendance</span></nav><h1>Classwise Attendance Report</h1><p>Real daily attendance across active classes.</p></div><a class="btn btn--secondary" href="<?=url('/admin/reports/attendance/students/pdf?from='.$selectedDate.'&to='.$selectedDate.'&class='.$selectedClass)?>"><i data-lucide="file-down"></i>PDF</a></header><form class="filter-bar filter-bar--compact"><div class="module-field"><label>Date</label><input class="module-input" type="date" name="date" value="<?=e($selectedDate)?>"></div><div class="module-field"><label>Class</label><select class="module-select" name="class"><option value="">All classes</option><?php foreach($classes as$c):?><option value="<?=$c['id']?>" <?=$selectedClass===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></div><button class="btn btn--primary">Apply</button></form><div class="metric-grid"><div class="metric-card"><span>Students</span><strong><?=$tot['students']?></strong></div><div class="metric-card"><span>Present</span><strong><?=$tot['present']?></strong></div><div class="metric-card"><span>Absent</span><strong><?=$tot['absent']?></strong></div><div class="metric-card"><span>Late / Leave</span><strong><?=$tot['late']?> / <?=$tot['leave']?></strong></div></div><section class="module-card"><header class="module-card__header"><div><h2>Class Breakdown</h2><p><?=e($selectedDate)?> · <?=$rate?>% present among marked records</p></div></header><div class="module-card__body"><div class="table-scroll"><table class="data-table"><thead><tr><th>Class</th><th>Students</th><th>Marked</th><th>Present</th><th>Absent</th><th>Late</th><th>Leave</th><th>Rate</th></tr></thead><tbody><?php foreach($rows as$r):$rr=$r['marked']?round($r['present_count']/$r['marked']*100,1):0;?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=$r['student_count']?></td><td><?=$r['marked']?></td><td><?=$r['present_count']?></td><td><?=$r['absent_count']?></td><td><?=$r['late_count']?></td><td><?=$r['leave_count']?></td><td><?=$rr?>%</td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="8"><div class="compact-empty"><h3>No classes found</h3><p>Create an active class before marking attendance.</p></div></td></tr><?php endif?></tbody></table></div></div></section></div></div></main>
